INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'ماكينة تكلفتها 480,000 وعمرها 8 سنين بدون قيمة متبقية، بقت جاهزة للاستخدام 1 أبريل وبدأ تشغيلها فعليًا 1 يوليو. إهلاك السنة المنتهية 31 ديسمبر:', '["30,000 جنيه","60,000 جنيه","40,000 جنيه","45,000 جنيه"]', 3, 'الإهلاك بيبدأ من الجاهزية للاستخدام: 60,000 × 9/12 = 45,000 (IAS 16.55).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'ماكينة تكلفتها 480,000 وعمرها 8 سنين بدون قيمة متبقية، بقت جاهزة للاستخدام 1 أبريل وبدأ تشغيلها فعليًا 1 يوليو. إهلاك السنة المنتهية 31 ديسمبر:');
