INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'ماكينة تكلفتها 500,000 وقيمتها المتبقية 20,000، وطاقتها الكلية 240,000 وحدة. أنتجت 60,000 وحدة في السنة الأولى. الإهلاك بطريقة وحدات الإنتاج:', '["96,000 جنيه","125,000 جنيه","100,000 جنيه","120,000 جنيه"]', 3, '480,000 ÷ 240,000 = 2 جنيه للوحدة × 60,000 = 120,000.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'ماكينة تكلفتها 500,000 وقيمتها المتبقية 20,000، وطاقتها الكلية 240,000 وحدة. أنتجت 60,000 وحدة في السنة الأولى. الإهلاك بطريقة وحدات الإنتاج:');
