INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), '500 وحدة تكلفة الوحدة 70. سعر البيع المتوقع 80، وتكاليف إكمال 12، وتكاليف بيع 6. التخفيض الكلي:', '["6,000 جنيه","3,000 جنيه","4,000 جنيه","صفر"]', 2, 'NRV = 80 − 12 − 6 = 62. التخفيض = (70 − 62) × 500 = 4,000.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = '500 وحدة تكلفة الوحدة 70. سعر البيع المتوقع 80، وتكاليف إكمال 12، وتكاليف بيع 6. التخفيض الكلي:');
