INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'استثمار عقاري بالقيمة العادلة اتحول لمقر للشركة وقيمته العادلة يوم التحويل 4,200,000، وعمره الباقي 20 سنة. الإهلاك السنوي:', '["صفر","210,000 جنيه","140,000 جنيه","420,000 جنيه"]', 1, 'القيمة العادلة يوم التحويل بتبقى التكلفة الجديدة: 4,200,000 ÷ 20 = 210,000 (IAS 40.60).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'استثمار عقاري بالقيمة العادلة اتحول لمقر للشركة وقيمته العادلة يوم التحويل 4,200,000، وعمره الباقي 20 سنة. الإهلاك السنوي:');
